from pathlib import Path
svg='<svg xmlns="http://www.w3.org/2000/svg" width="680" height="140" viewBox="0 0 680 140" role="img">\n<title>Joke card</title><desc>joke setup punchline reveal 1s</desc>\n<style>@media (prefers-reduced-motion: reduce){*{animation:none!important;transition:none!important}} .punch{opacity:0;animation:fade .5s 1.2s forwards} @keyframes fade{to{opacity:1}} </style>\n<rect width="680" height="140" rx="16" fill="#1e1b4b"/>\n<text x="24" y="36" fill="#a5b4fc" font-family="monospace" font-size="11">JOKE — readme-jokes.vercel.app/api</text>\n<text x="24" y="68" fill="#e0e7ff" font-family="monospace" font-size="13">Why do programmers prefer dark mode?</text>\n<text x="24" y="94" fill="#fde68a" font-family="monospace" font-size="13" class="punch">Because light attracts bugs! 🐛</text>\n<text x="520" y="118" fill="#818cf8" font-family="monospace" font-size="9">?hideBorder &amp; theme support</text>\n</svg>\n'
